/* LUT Study Site — Real-Time Chapter Materials & Uploads Engine
 * Supports:
 *   1. Supabase Live Backend (Storage + Postgres + Realtime WebSocket / Polling)
 *   2. Static Repo Uploads (data/uploads.json generated by build.py)
 *   3. Local Browser Preview Mode (IndexedDB) when Supabase is not yet configured
 *   4. GitHub Issue Submission fallback
 */
(function () {
  "use strict";

  var CFG = Object.assign(
    {
      supabaseUrl: "",
      supabaseAnonKey: "",
      storageBucket: "materials",
      tableName: "chapter_materials",
      requirePasscode: false,
      githubRepo: "",
      maxFileSizeMB: 25,
      allowedExtensions: [
        ".pdf", ".pptx", ".ppt", ".docx", ".doc",
        ".md", ".txt", ".png", ".jpg", ".jpeg", ".webp",
        ".zip", ".py", ".ipynb", ".xlsx", ".csv"
      ]
    },
    window.STUDY_SITE_CONFIG || {}
  );

  var PREFIX = (function () {
    var el = document.querySelector("[data-site-prefix]");
    return el ? el.getAttribute("data-site-prefix") || "" : "";
  })();

  var IS_CLOUD = Boolean(CFG.supabaseUrl && CFG.supabaseAnonKey);
  var SB_URL = (CFG.supabaseUrl || "").replace(/\/+$/, "");
  var SB_KEY = CFG.supabaseAnonKey || "";
  var POLL_MS = 8000;
  var BC = typeof BroadcastChannel !== "undefined" ? new BroadcastChannel("lut-study-materials") : null;

  /* ---------------- Utilities ---------------- */
  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function fmtSize(bytes) {
    if (!bytes && bytes !== 0) return "";
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(2) + " MB";
  }

  function fmtTime(iso) {
    if (!iso) return "";
    try {
      var d = new Date(iso);
      if (isNaN(d.getTime())) return String(iso);
      return d.toLocaleString(undefined, {
        year: "numeric", month: "2-digit", day: "2-digit",
        hour: "2-digit", minute: "2-digit"
      });
    } catch (e) {
      return String(iso);
    }
  }

  function getExt(name) {
    var m = /\.([a-zA-Z0-9]+)$/.exec(name || "");
    return m ? "." + m[1].toLowerCase() : "";
  }

  function fileBadge(item) {
    if (item.kind === "note") return { label: "MD 笔记", cls: "purple" };
    var ext = getExt(item.file_name || "");
    if (ext === ".pdf") return { label: "PDF", cls: "bad" };
    if (ext === ".pptx" || ext === ".ppt") return { label: "PPT", cls: "warn" };
    if (ext === ".docx" || ext === ".doc") return { label: "DOCX", cls: "" };
    if ([".png", ".jpg", ".jpeg", ".webp"].indexOf(ext) >= 0) return { label: "IMG", cls: "ok" };
    if (ext === ".md" || ext === ".txt") return { label: ext.slice(1).toUpperCase(), cls: "purple" };
    if (ext === ".py" || ext === ".ipynb") return { label: "CODE", cls: "ok" };
    return { label: (ext ? ext.slice(1).toUpperCase() : "FILE"), cls: "mute" };
  }

  function renderMarkdown(md) {
    var text = esc(md || "");
    text = text.replace(/```([\s\S]*?)```/g, function (_, code) {
      return "<pre><code>" + code.trim() + "</code></pre>";
    });
    text = text.replace(/`([^`]+)`/g, "<code>$1</code>");
    text = text.replace(/^### (.+)$/gm, "<h4>$1</h4>");
    text = text.replace(/^## (.+)$/gm, "<h3>$1</h3>");
    text = text.replace(/^# (.+)$/gm, "<h3>$1</h3>");
    text = text.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    text = text.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    text = text.replace(/^\s*[-*] (.+)$/gm, "<li>$1</li>");
    text = text.replace(/(<li>[\s\S]*?<\/li>)/g, "<ul>$1</ul>");
    text = text.replace(/<\/ul>\s*<ul>/g, "");
    text = text.replace(/\n{2,}/g, "</p><p>");
    text = "<p>" + text.replace(/\n/g, "<br>") + "</p>";
    return text.replace(/<p><\/p>/g, "");
  }

  function sanitizeFilename(name) {
    return (name || "file")
      .replace(/[^\w.\-\u4e00-\u9fff]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 120) || "upload";
  }

  /* ---------------- Local IndexedDB Store (Fallback / Preview Mode) ---------------- */
  var IDB_NAME = "lut_study_materials_v1";
  var IDB_STORE = "materials";

  function openIDB() {
    return new Promise(function (resolve, reject) {
      if (!window.indexedDB) return reject(new Error("IndexedDB unavailable"));
      var req = indexedDB.open(IDB_NAME, 1);
      req.onupgradeneeded = function () {
        var db = req.result;
        if (!db.objectStoreNames.contains(IDB_STORE)) {
          var st = db.createObjectStore(IDB_STORE, { keyPath: "id" });
          st.createIndex("course_part", ["course_id", "part_index"], { unique: false });
        }
      };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error); };
    });
  }

  function idbGetAll() {
    return openIDB().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(IDB_STORE, "readonly");
        var req = tx.objectStore(IDB_STORE).getAll();
        req.onsuccess = function () { resolve(req.result || []); };
        req.onerror = function () { reject(req.error); };
      });
    }).catch(function () { return []; });
  }

  function idbPut(record) {
    return openIDB().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(IDB_STORE, "readwrite");
        var req = tx.objectStore(IDB_STORE).put(record);
        req.onsuccess = function () { resolve(record); };
        req.onerror = function () { reject(req.error); };
      });
    });
  }

  function idbDelete(id) {
    return openIDB().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(IDB_STORE, "readwrite");
        var req = tx.objectStore(IDB_STORE).delete(id);
        req.onsuccess = function () { resolve(); };
        req.onerror = function () { reject(req.error); };
      });
    });
  }

  /* ---------------- Static Repo Uploads (data/uploads.json) ---------------- */
  var staticUploadsCache = null;
  function fetchStaticUploads() {
    if (staticUploadsCache !== null) return Promise.resolve(staticUploadsCache);
    return fetch(PREFIX + "data/uploads.json?_=" + Date.now())
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (arr) {
        staticUploadsCache = Array.isArray(arr) ? arr.map(function (it) {
          return Object.assign({}, it, {
            _source: "repo",
            file_url: it.file_path ? (PREFIX + it.file_path) : ""
          });
        }) : [];
        return staticUploadsCache;
      })
      .catch(function () {
        staticUploadsCache = [];
        return [];
      });
  }

  /* ---------------- Catalog Loader (data/catalog.json) ---------------- */
  var catalogCache = null;
  function fetchCatalog() {
    if (catalogCache !== null) return Promise.resolve(catalogCache);
    return fetch(PREFIX + "data/catalog.json")
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (arr) {
        catalogCache = Array.isArray(arr) ? arr : [];
        return catalogCache;
      })
      .catch(function () {
        catalogCache = [];
        return [];
      });
  }

  /* ---------------- Supabase Cloud Client (Pure Fetch + Optional Realtime) ---------------- */
  function sbHeaders(extra) {
    return Object.assign(
      {
        apikey: SB_KEY,
        Authorization: "Bearer " + SB_KEY
      },
      extra || {}
    );
  }

  function sbPublicUrl(path) {
    if (!path) return "";
    return SB_URL + "/storage/v1/object/public/" + encodeURIComponent(CFG.storageBucket) + "/" +
      path.split("/").map(encodeURIComponent).join("/");
  }

  function sbList(filter) {
    var params = ["select=*", "order=created_at.desc", "limit=200"];
    if (filter && filter.course_id) params.push("course_id=eq." + encodeURIComponent(filter.course_id));
    if (filter && filter.part_index) params.push("part_index=eq." + encodeURIComponent(filter.part_index));
    var url = SB_URL + "/rest/v1/" + encodeURIComponent(CFG.tableName) + "?" + params.join("&");
    return fetch(url, { headers: sbHeaders({ Accept: "application/json" }) })
      .then(function (r) {
        if (!r.ok) return r.text().then(function (t) { throw new Error("Supabase query failed (" + r.status + "): " + t); });
        return r.json();
      })
      .then(function (rows) {
        return (rows || []).map(function (row) {
          return Object.assign({}, row, {
            _source: "cloud",
            file_url: row.file_path ? sbPublicUrl(row.file_path) : ""
          });
        });
      });
  }

  function sbUploadFile(courseId, partIndex, file) {
    var safeName = Date.now() + "_" + Math.random().toString(36).slice(2, 7) + "_" + sanitizeFilename(file.name);
    var path = courseId + "/part-" + partIndex + "/" + safeName;
    var url = SB_URL + "/storage/v1/object/" + encodeURIComponent(CFG.storageBucket) + "/" +
      path.split("/").map(encodeURIComponent).join("/");
    return fetch(url, {
      method: "POST",
      headers: sbHeaders({
        "Content-Type": file.type || "application/octet-stream",
        "x-upsert": "false"
      }),
      body: file
    }).then(function (r) {
      if (!r.ok) return r.text().then(function (t) { throw new Error("文件上传失败 (" + r.status + "): " + t); });
      return path;
    });
  }

  function sbInsertMaterial(payload, passcode) {
    if (CFG.requirePasscode) {
      var rpcUrl = SB_URL + "/rest/v1/rpc/submit_material";
      return fetch(rpcUrl, {
        method: "POST",
        headers: sbHeaders({ "Content-Type": "application/json", Prefer: "return=representation" }),
        body: JSON.stringify({
          p_passcode: passcode || "",
          p_course_id: payload.course_id,
          p_part_index: payload.part_index,
          p_part_name: payload.part_name,
          p_title: payload.title,
          p_description: payload.description || "",
          p_kind: payload.kind,
          p_file_name: payload.file_name || null,
          p_file_path: payload.file_path || null,
          p_file_size: payload.file_size || null,
          p_mime_type: payload.mime_type || null,
          p_note_markdown: payload.note_markdown || null,
          p_uploader: payload.uploader || "Anonymous"
        })
      }).then(function (r) {
        if (!r.ok) return r.text().then(function (t) { throw new Error("提交失败 (" + r.status + "): " + t); });
        return r.json();
      });
    }
    var url = SB_URL + "/rest/v1/" + encodeURIComponent(CFG.tableName);
    return fetch(url, {
      method: "POST",
      headers: sbHeaders({ "Content-Type": "application/json", Prefer: "return=representation" }),
      body: JSON.stringify(payload)
    }).then(function (r) {
      if (!r.ok) return r.text().then(function (t) { throw new Error("保存记录失败 (" + r.status + "): " + t); });
      return r.json();
    });
  }

  /* ---------------- Unified Data API ---------------- */
  function loadMaterials(filter) {
    var staticP = fetchStaticUploads().then(function (items) {
      return items.filter(function (it) {
        if (filter && filter.course_id && String(it.course_id) !== String(filter.course_id)) return false;
        if (filter && filter.part_index && Number(it.part_index) !== Number(filter.part_index)) return false;
        return true;
      });
    });

    var dynamicP = IS_CLOUD
      ? sbList(filter)
      : idbGetAll().then(function (items) {
          return items
            .filter(function (it) {
              if (filter && filter.course_id && String(it.course_id) !== String(filter.course_id)) return false;
              if (filter && filter.part_index && Number(it.part_index) !== Number(filter.part_index)) return false;
              return true;
            })
            .map(function (it) {
              return Object.assign({}, it, { _source: "local" });
            });
        });

    return Promise.all([dynamicP, staticP]).then(function (res) {
      var merged = [].concat(res[0] || [], res[1] || []);
      merged.sort(function (a, b) {
        return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
      });
      return merged;
    });
  }

  function submitMaterial(opts) {
    var file = opts.file || null;
    if (opts.kind === "file") {
      if (!file) return Promise.reject(new Error("请选择要上传的文件 / Please choose a file."));
      var maxBytes = (CFG.maxFileSizeMB || 25) * 1024 * 1024;
      if (file.size > maxBytes) {
        return Promise.reject(new Error("文件超过大小限制 (" + CFG.maxFileSizeMB + " MB)"));
      }
      var ext = getExt(file.name);
      if (CFG.allowedExtensions && CFG.allowedExtensions.length && CFG.allowedExtensions.indexOf(ext) < 0) {
        return Promise.reject(new Error("不支持的文件格式: " + (ext || "未知") + "。支持: " + CFG.allowedExtensions.join(" ")));
      }
    } else {
      if (!opts.note_markdown || !opts.note_markdown.trim()) {
        return Promise.reject(new Error("请输入笔记内容 / Please enter note content."));
      }
    }

    var basePayload = {
      course_id: String(opts.course_id),
      part_index: Number(opts.part_index),
      part_name: opts.part_name || ("Part " + opts.part_index),
      title: (opts.title || (file ? file.name : "章节补充笔记")).trim(),
      description: (opts.description || "").trim(),
      kind: opts.kind,
      file_name: file ? file.name : null,
      file_size: file ? file.size : null,
      mime_type: file ? (file.type || "application/octet-stream") : null,
      note_markdown: opts.kind === "note" ? opts.note_markdown : null,
      uploader: (opts.uploader || "同学").trim() || "同学"
    };

    if (IS_CLOUD) {
      var uploadP = file ? sbUploadFile(basePayload.course_id, basePayload.part_index, file) : Promise.resolve(null);
      return uploadP
        .then(function (filePath) {
          basePayload.file_path = filePath;
          return sbInsertMaterial(basePayload, opts.passcode);
        })
        .then(function (res) {
          if (BC) BC.postMessage({ type: "updated", course_id: basePayload.course_id, part_index: basePayload.part_index });
          return res;
        });
    }

    // Local Browser Preview Mode (IndexedDB)
    var record = Object.assign({}, basePayload, {
      id: "local-" + Date.now() + "-" + Math.random().toString(36).slice(2, 7),
      created_at: new Date().toISOString(),
      file_blob: file || null,
      _source: "local"
    });
    return idbPut(record).then(function (saved) {
      if (BC) BC.postMessage({ type: "updated", course_id: basePayload.course_id, part_index: basePayload.part_index });
      return saved;
    });
  }

  /* ---------------- Preview Modal ---------------- */
  var modalEl = null;
  function ensureModal() {
    if (modalEl) return modalEl;
    modalEl = document.createElement("div");
    modalEl.className = "mat-modal";
    modalEl.innerHTML =
      '<div class="mat-modal-box" role="dialog" aria-modal="true">' +
        '<div class="mat-modal-head">' +
          '<div class="mat-modal-title"></div>' +
          '<button type="button" class="mat-close" aria-label="关闭">✕</button>' +
        "</div>" +
        '<div class="mat-modal-body"></div>' +
      "</div>";
    modalEl.addEventListener("click", function (e) {
      if (e.target === modalEl || e.target.classList.contains("mat-close")) closeModal();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && modalEl.classList.contains("open")) closeModal();
    });
    document.body.appendChild(modalEl);
    return modalEl;
  }

  var activeObjectUrls = [];
  function closeModal() {
    if (!modalEl) return;
    modalEl.classList.remove("open");
    modalEl.querySelector(".mat-modal-body").innerHTML = "";
    activeObjectUrls.forEach(function (u) { try { URL.revokeObjectURL(u); } catch (e) {} });
    activeObjectUrls = [];
  }

  function openPreview(item) {
    var m = ensureModal();
    m.querySelector(".mat-modal-title").textContent = item.title || item.file_name || "资料预览";
    var body = m.querySelector(".mat-modal-body");

    if (item.kind === "note") {
      body.innerHTML =
        '<div class="mat-meta-line">' +
          '<span>上传者：' + esc(item.uploader || "同学") + "</span>" +
          '<span>时间：' + esc(fmtTime(item.created_at)) + "</span>" +
        "</div>" +
        '<div class="mat-md-view">' + renderMarkdown(item.note_markdown || "") + "</div>";
      m.classList.add("open");
      return;
    }

    var url = item.file_url || "";
    if (!url && item.file_blob) {
      url = URL.createObjectURL(item.file_blob);
      activeObjectUrls.push(url);
    }
    var ext = getExt(item.file_name || "");
    if (!url) {
      body.innerHTML = "<p>无法加载文件预览。</p>";
    } else if (ext === ".pdf") {
      body.innerHTML = '<iframe class="mat-preview-frame" src="' + esc(url) + '"></iframe>';
    } else if ([".png", ".jpg", ".jpeg", ".webp"].indexOf(ext) >= 0) {
      body.innerHTML = '<img class="mat-preview-img" src="' + esc(url) + '" alt="' + esc(item.file_name) + '">';
    } else if ([".md", ".txt", ".py", ".csv"].indexOf(ext) >= 0) {
      body.innerHTML = "<p class=\"sub\">加载中…</p>";
      fetch(url)
        .then(function (r) { return r.text(); })
        .then(function (txt) {
          body.innerHTML = ext === ".md"
            ? '<div class="mat-md-view">' + renderMarkdown(txt) + "</div>"
            : "<pre><code>" + esc(txt) + "</code></pre>";
        })
        .catch(function () {
          body.innerHTML = '<p>无法在线预览该文本文件，请点击下载查看。</p>';
        });
    } else {
      body.innerHTML =
        '<div class="callout"><b>提示</b>浏览器不支持直接内嵌预览 <code>' + esc(ext || "该格式") + "</code> 文件，请直接下载到本地打开。</div>" +
        '<p><a class="mat-btn primary" href="' + esc(url) + '" download="' + esc(item.file_name || "download") + '" target="_blank" rel="noopener">下载 ' + esc(item.file_name || "文件") + "</a></p>";
    }
    m.classList.add("open");
  }

  function downloadItem(item) {
    var url = item.file_url || "";
    var revoke = false;
    if (!url && item.file_blob) {
      url = URL.createObjectURL(item.file_blob);
      revoke = true;
    }
    if (!url && item.kind === "note") {
      var blob = new Blob(["# " + (item.title || "Note") + "\n\n" + (item.note_markdown || "")], { type: "text/markdown;charset=utf-8" });
      url = URL.createObjectURL(blob);
      revoke = true;
    }
    if (!url) return;
    var a = document.createElement("a");
    a.href = url;
    a.download = item.file_name || (sanitizeFilename(item.title || "note") + ".md");
    a.target = "_blank";
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    if (revoke) setTimeout(function () { URL.revokeObjectURL(url); }, 3000);
  }

  /* ---------------- GitHub Issue Fallback Link ---------------- */
  function githubIssueUrl(courseId, partName) {
    if (!CFG.githubRepo) return "";
    var title = encodeURIComponent("[Material] " + (courseId || "") + " - " + (partName || ""));
    var body = encodeURIComponent(
      "### 课程 ID / Course ID\n" + (courseId || "") +
      "\n\n### 对应章节 / Chapter\n" + (partName || "") +
      "\n\n### 资料说明 / Notes\n（请把 PDF/PPTX/DOCX/图片直接拖入下方编辑框，或粘贴笔记内容）\n"
    );
    return "https://github.com/" + CFG.githubRepo + "/issues/new?title=" + title + "&body=" + body + "&labels=material-upload";
  }

  /* ---------------- Render Material List ---------------- */
  function renderMaterialCards(container, items, opts) {
    opts = opts || {};
    if (!items || !items.length) {
      container.innerHTML =
        '<div class="mat-empty">本章节还没有同学上传补充资料或笔记。成为第一个分享者吧！</div>';
      return;
    }
    container.innerHTML = items.map(function (it, idx) {
      var b = fileBadge(it);
      var srcTag = it._source === "cloud"
        ? '<span class="badge ok">实时云端</span>'
        : it._source === "repo"
          ? '<span class="badge">GitHub 仓库</span>'
          : '<span class="badge warn">本机预览</span>';
      var locTag = opts.showLocation
        ? '<span class="badge mute">' + esc(it.course_id) + " · " + esc(it.part_name || ("Part " + it.part_index)) + "</span>"
        : "";
      var sizeStr = it.file_size ? " · " + fmtSize(it.file_size) : "";
      var desc = it.description ? '<p class="mat-desc">' + esc(it.description) + "</p>" : "";
      var previewSnippet = it.kind === "note" && it.note_markdown
        ? '<p class="mat-desc">' + esc(it.note_markdown.replace(/\s+/g, " ").slice(0, 140)) + (it.note_markdown.length > 140 ? "…" : "") + "</p>"
        : "";
      var delBtn = it._source === "local"
        ? '<button type="button" class="mat-btn ghost" data-act="delete" data-idx="' + idx + '">删除</button>'
        : "";
      return (
        '<div class="mat-item">' +
          '<div class="mat-item-main">' +
            '<div class="mat-item-head">' +
              '<span class="badge ' + esc(b.cls) + '">' + esc(b.label) + "</span>" +
              srcTag + locTag +
              '<strong class="mat-item-title">' + esc(it.title || it.file_name || "未命名资料") + "</strong>" +
            "</div>" +
            (desc || previewSnippet) +
            '<div class="mat-item-meta">' +
              (it.file_name ? "<code>" + esc(it.file_name) + "</code>" + esc(sizeStr) + " · " : "") +
              "上传者：" + esc(it.uploader || "同学") + " · " + esc(fmtTime(it.created_at)) +
            "</div>" +
          "</div>" +
          '<div class="mat-item-actions">' +
            '<button type="button" class="mat-btn" data-act="preview" data-idx="' + idx + '">预览</button>' +
            '<button type="button" class="mat-btn primary" data-act="download" data-idx="' + idx + '">下载</button>' +
            delBtn +
          "</div>" +
        "</div>"
      );
    }).join("");

    container.querySelectorAll("button[data-act]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var item = items[Number(btn.getAttribute("data-idx"))];
        var act = btn.getAttribute("data-act");
        if (!item) return;
        if (act === "preview") openPreview(item);
        else if (act === "download") downloadItem(item);
        else if (act === "delete" && item._source === "local") {
          idbDelete(item.id).then(function () {
            if (opts.onChange) opts.onChange();
          });
        }
      });
    });
  }

  /* ---------------- Build Upload Form Widget ---------------- */
  function buildFormHTML(opts) {
    var showCourseSelect = Boolean(opts.showCourseSelect);
    var showPartSelect = Boolean(opts.showPartSelect);
    var passField = CFG.requirePasscode
      ? '<label class="mat-field"><span>班级口令 / Passcode *</span><input type="password" name="passcode" required placeholder="输入上传口令"></label>'
      : "";
    var ghUrl = githubIssueUrl(opts.courseId, opts.partName);
    var ghBtn = ghUrl
      ? '<a class="mat-btn ghost" href="' + esc(ghUrl) + '" target="_blank" rel="noopener">通过 GitHub Issue 提交 ↗</a>'
      : "";

    return (
      '<div class="mat-tabs" role="tablist">' +
        '<button type="button" class="mat-tab active" data-mode="file">📎 上传课件 / 资料文件</button>' +
        '<button type="button" class="mat-tab" data-mode="note">📝 在线写 Markdown 笔记</button>' +
      "</div>" +
      '<form class="mat-form">' +
        (showCourseSelect || showPartSelect
          ? '<div class="mat-grid">' +
              (showCourseSelect
                ? '<label class="mat-field"><span>选择课程 / Course *</span><select name="course_id" required></select></label>'
                : "") +
              (showPartSelect
                ? '<label class="mat-field"><span>选择章节 / Chapter *</span><select name="part_index" required></select></label>'
                : "") +
            "</div>"
          : "") +
        '<div class="mat-grid">' +
          '<label class="mat-field"><span>资料标题 / Title</span><input type="text" name="title" placeholder="例如：Week 5 课堂手写笔记 / 补充习题解答（留空自动用文件名）"></label>' +
          '<label class="mat-field"><span>署名 / Uploader</span><input type="text" name="uploader" placeholder="昵称或姓名（选填，默认“同学”）"></label>' +
        "</div>" +
        '<div class="mat-mode-file">' +
          '<label class="mat-dropzone">' +
            '<input type="file" name="file" class="mat-file-input">' +
            '<div class="mat-drop-text"><strong>点击选择文件</strong> 或将 PDF / PPTX / DOCX / 图片 / Markdown 拖到这里</div>' +
            '<div class="mat-drop-sub">单文件最大 ' + esc(CFG.maxFileSizeMB) + " MB</div>" +
          "</label>" +
          '<label class="mat-field"><span>补充说明 / Description（选填）</span><input type="text" name="description" placeholder="一句话说明这份资料包含什么、对应哪一页或哪道题"></label>' +
        "</div>" +
        '<div class="mat-mode-note" style="display:none">' +
          '<label class="mat-field"><span>Markdown 笔记内容 *</span><textarea name="note_markdown" rows="6" placeholder="支持 # 标题、**加粗**、`代码`、- 列表……"></textarea></label>' +
        "</div>" +
        passField +
        '<div class="mat-form-foot">' +
          '<button type="submit" class="mat-btn primary">立即发布到本章节</button>' +
          ghBtn +
          '<span class="mat-status" aria-live="polite"></span>' +
        "</div>" +
      "</form>"
    );
  }

  function wireForm(root, opts) {
    var form = root.querySelector(".mat-form");
    var tabs = root.querySelectorAll(".mat-tab");
    var filePane = root.querySelector(".mat-mode-file");
    var notePane = root.querySelector(".mat-mode-note");
    var dropzone = root.querySelector(".mat-dropzone");
    var fileInput = root.querySelector(".mat-file-input");
    var dropText = root.querySelector(".mat-drop-text");
    var statusEl = root.querySelector(".mat-status");
    var mode = "file";
    var droppedFile = null;

    tabs.forEach(function (t) {
      t.addEventListener("click", function () {
        mode = t.getAttribute("data-mode");
        tabs.forEach(function (x) { x.classList.toggle("active", x === t); });
        filePane.style.display = mode === "file" ? "" : "none";
        notePane.style.display = mode === "note" ? "" : "none";
      });
    });

    function showSelectedFile(f) {
      if (!f) {
        dropText.innerHTML = "<strong>点击选择文件</strong> 或将 PDF / PPTX / DOCX / 图片 / Markdown 拖到这里";
        return;
      }
      dropText.innerHTML = "已选择：<strong>" + esc(f.name) + "</strong>（" + esc(fmtSize(f.size)) + "）";
    }

    fileInput.addEventListener("change", function () {
      droppedFile = fileInput.files && fileInput.files[0] ? fileInput.files[0] : null;
      showSelectedFile(droppedFile);
    });

    ["dragenter", "dragover"].forEach(function (ev) {
      dropzone.addEventListener(ev, function (e) {
        e.preventDefault();
        dropzone.classList.add("drag");
      });
    });
    ["dragleave", "drop"].forEach(function (ev) {
      dropzone.addEventListener(ev, function (e) {
        e.preventDefault();
        dropzone.classList.remove("drag");
      });
    });
    dropzone.addEventListener("drop", function (e) {
      var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      if (f) {
        droppedFile = f;
        showSelectedFile(f);
      }
    });

    // Save uploader nickname locally for convenience
    var uploaderInput = form.querySelector('input[name="uploader"]');
    try {
      var savedName = localStorage.getItem("lut-uploader-name");
      if (savedName && uploaderInput) uploaderInput.value = savedName;
    } catch (e) {}

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var courseId = opts.getCourseId ? opts.getCourseId() : opts.courseId;
      var partInfo = opts.getPartInfo ? opts.getPartInfo() : { index: opts.partIndex, name: opts.partName };
      if (!courseId || !partInfo || !partInfo.index) {
        statusEl.textContent = "请先选择课程和章节。";
        statusEl.className = "mat-status err";
        return;
      }
      var submitBtn = form.querySelector('button[type="submit"]');
      submitBtn.disabled = true;
      statusEl.textContent = IS_CLOUD ? "正在上传并实时同步…" : "正在保存到本地预览…";
      statusEl.className = "mat-status";

      var uploaderVal = uploaderInput ? uploaderInput.value.trim() : "";
      try { if (uploaderVal) localStorage.setItem("lut-uploader-name", uploaderVal); } catch (err) {}

      submitMaterial({
        course_id: courseId,
        part_index: partInfo.index,
        part_name: partInfo.name,
        title: (form.querySelector('input[name="title"]') || {}).value || "",
        description: (form.querySelector('input[name="description"]') || {}).value || "",
        uploader: uploaderVal,
        passcode: (form.querySelector('input[name="passcode"]') || {}).value || "",
        kind: mode,
        file: mode === "file" ? droppedFile : null,
        note_markdown: mode === "note" ? ((form.querySelector('textarea[name="note_markdown"]') || {}).value || "") : null
      })
        .then(function () {
          form.reset();
          if (uploaderInput && uploaderVal) uploaderInput.value = uploaderVal;
          droppedFile = null;
          showSelectedFile(null);
          statusEl.textContent = IS_CLOUD ? "✓ 发布成功！所有人已实时可见。" : "✓ 已保存到本机浏览器预览。";
          statusEl.className = "mat-status ok";
          if (opts.onSubmitted) opts.onSubmitted();
        })
        .catch(function (err) {
          statusEl.textContent = "✗ " + (err && err.message ? err.message : String(err));
          statusEl.className = "mat-status err";
        })
        .finally(function () {
          submitBtn.disabled = false;
        });
    });
  }

  /* ---------------- Mode Status Banner ---------------- */
  function modeBannerHTML() {
    if (IS_CLOUD) {
      return '<span class="mat-live-pill"><span class="mat-dot"></span>实时云端同步已开启</span>';
    }
    return (
      '<span class="mat-live-pill local"><span class="mat-dot"></span>本机预览模式</span>' +
      '<span class="mat-hint">（当前上传保存在本机浏览器；在 <code>assets/config.js</code> 填入免费 Supabase 配置后，即可全员实时共享）</span>'
    );
  }

  /* ---------------- Mount 1: Chapter Page (#chapter-materials) ---------------- */
  function initChapterMount(el) {
    var courseId = el.getAttribute("data-course");
    var partIndex = Number(el.getAttribute("data-part"));
    var partName = el.getAttribute("data-part-name") || ("Part " + partIndex);

    el.innerHTML =
      '<div class="mat-head">' +
        '<div><h2>本章补充资料与同学上传</h2><div class="mat-sub">' + modeBannerHTML() + "</div></div>" +
        '<button type="button" class="mat-btn primary" data-toggle-form>+ 上传本章资料 / 笔记</button>' +
      "</div>" +
      '<div class="mat-drawer" style="display:none"></div>' +
      '<div class="mat-list"><div class="mat-empty">加载中…</div></div>';

    var drawer = el.querySelector(".mat-drawer");
    var listEl = el.querySelector(".mat-list");
    var toggleBtn = el.querySelector("[data-toggle-form]");

    drawer.innerHTML = buildFormHTML({ courseId: courseId, partIndex: partIndex, partName: partName });

    toggleBtn.addEventListener("click", function () {
      var open = drawer.style.display === "none";
      drawer.style.display = open ? "" : "none";
      toggleBtn.textContent = open ? "收起上传表单" : "+ 上传本章资料 / 笔记";
    });

    function refresh() {
      loadMaterials({ course_id: courseId, part_index: partIndex }).then(function (items) {
        renderMaterialCards(listEl, items, { onChange: refresh });
      });
    }

    wireForm(drawer, {
      courseId: courseId,
      partIndex: partIndex,
      partName: partName,
      onSubmitted: refresh
    });

    refresh();
    startRealtimeWatcher(refresh);
  }

  /* ---------------- Mount 2: Course Page (#course-materials) ---------------- */
  function initCourseMount(el) {
    var courseId = el.getAttribute("data-course");
    var parts = [];
    try { parts = JSON.parse(el.getAttribute("data-parts") || "[]"); } catch (e) {}

    el.innerHTML =
      '<div class="mat-head">' +
        '<div><h2>本课实时资料库（按章节归档）</h2><div class="mat-sub">' + modeBannerHTML() + "</div></div>" +
        '<button type="button" class="mat-btn primary" data-toggle-form>+ 上传讲义 / 笔记到本课</button>' +
      "</div>" +
      '<div class="mat-drawer" style="display:none"></div>' +
      '<div class="mat-filter-row">' +
        '<label>按章节筛选：<select class="mat-filter-part"><option value="">全部章节</option>' +
        parts.map(function (p) {
          return '<option value="' + esc(p.index) + '">' + esc(p.name) + "</option>";
        }).join("") +
        "</select></label>" +
      "</div>" +
      '<div class="mat-list"><div class="mat-empty">加载中…</div></div>';

    var drawer = el.querySelector(".mat-drawer");
    var listEl = el.querySelector(".mat-list");
    var toggleBtn = el.querySelector("[data-toggle-form]");
    var filterPart = el.querySelector(".mat-filter-part");

    drawer.innerHTML = buildFormHTML({ courseId: courseId, showPartSelect: true });
    var partSelect = drawer.querySelector('select[name="part_index"]');
    partSelect.innerHTML = parts.map(function (p) {
      return '<option value="' + esc(p.index) + '" data-name="' + esc(p.name) + '">' + esc(p.name) + "</option>";
    }).join("");

    toggleBtn.addEventListener("click", function () {
      var open = drawer.style.display === "none";
      drawer.style.display = open ? "" : "none";
      toggleBtn.textContent = open ? "收起上传表单" : "+ 上传讲义 / 笔记到本课";
    });

    function refresh() {
      var pi = filterPart.value ? Number(filterPart.value) : null;
      loadMaterials({ course_id: courseId, part_index: pi }).then(function (items) {
        renderMaterialCards(listEl, items, { showLocation: !pi, onChange: refresh });
      });
    }

    filterPart.addEventListener("change", refresh);
    wireForm(drawer, {
      courseId: courseId,
      getPartInfo: function () {
        var opt = partSelect.options[partSelect.selectedIndex];
        return opt ? { index: Number(opt.value), name: opt.getAttribute("data-name") || opt.textContent } : null;
      },
      onSubmitted: refresh
    });

    refresh();
    startRealtimeWatcher(refresh);
  }

  /* ---------------- Mount 3: Global Upload Hub (#upload-hub) ---------------- */
  function initUploadHub(el) {
    fetchCatalog().then(function (catalog) {
      el.innerHTML =
        '<div class="mat-hub-status">' + modeBannerHTML() + "</div>" +
        '<div class="card"><h2>上传讲义、课件或章节笔记</h2>' +
          '<p class="sub">选择对应的课程与章节后提交，资料会立即出现在该章节页和下方实时动态中。</p>' +
          '<div class="mat-drawer"></div>' +
        "</div>" +
        '<div class="card">' +
          '<div class="mat-head"><h2>全站最新上传资料</h2>' +
            '<div class="mat-filter-row">' +
              '<select class="mat-filter-course"><option value="">全部课程</option>' +
              catalog.map(function (c) {
                return '<option value="' + esc(c.id) + '">' + esc(c.name_zh) + "</option>";
              }).join("") +
              "</select>" +
              '<select class="mat-filter-part"><option value="">全部章节</option></select>' +
            "</div>" +
          "</div>" +
          '<div class="mat-list"><div class="mat-empty">加载中…</div></div>' +
        "</div>";

      var drawer = el.querySelector(".mat-drawer");
      var listEl = el.querySelector(".mat-list");
      var filterCourse = el.querySelector(".mat-filter-course");
      var filterPart = el.querySelector(".mat-filter-part");

      drawer.innerHTML = buildFormHTML({ showCourseSelect: true, showPartSelect: true });
      var courseSelect = drawer.querySelector('select[name="course_id"]');
      var partSelect = drawer.querySelector('select[name="part_index"]');

      courseSelect.innerHTML = catalog.map(function (c) {
        return '<option value="' + esc(c.id) + '">' + esc(c.name_zh) + " (" + esc(c.id) + ")</option>";
      }).join("");

      function syncParts(cid, targetSelect, includeAll) {
        var c = catalog.find(function (x) { return String(x.id) === String(cid); });
        var opts = includeAll ? ['<option value="">全部章节</option>'] : [];
        if (c && c.parts) {
          c.parts.forEach(function (p) {
            opts.push('<option value="' + esc(p.index) + '" data-name="' + esc(p.name) + '">' + esc(p.name) + "</option>");
          });
        }
        targetSelect.innerHTML = opts.join("");
      }

      // Support ?course=30352&part=2 query params
      var qp = new URLSearchParams(window.location.search);
      if (qp.get("course") && catalog.some(function (c) { return String(c.id) === qp.get("course"); })) {
        courseSelect.value = qp.get("course");
      }
      syncParts(courseSelect.value, partSelect, false);
      if (qp.get("part")) partSelect.value = qp.get("part");

      courseSelect.addEventListener("change", function () {
        syncParts(courseSelect.value, partSelect, false);
      });

      filterCourse.addEventListener("change", function () {
        syncParts(filterCourse.value, filterPart, true);
        refresh();
      });
      filterPart.addEventListener("change", refresh);

      function refresh() {
        var f = {};
        if (filterCourse.value) f.course_id = filterCourse.value;
        if (filterPart.value) f.part_index = Number(filterPart.value);
        loadMaterials(f).then(function (items) {
          renderMaterialCards(listEl, items, { showLocation: true, onChange: refresh });
        });
      }

      wireForm(drawer, {
        getCourseId: function () { return courseSelect.value; },
        getPartInfo: function () {
          var opt = partSelect.options[partSelect.selectedIndex];
          return opt ? { index: Number(opt.value), name: opt.getAttribute("data-name") || opt.textContent } : null;
        },
        onSubmitted: refresh
      });

      refresh();
      startRealtimeWatcher(refresh);
    });
  }

  /* ---------------- Live Sync Watcher ---------------- */
  function startRealtimeWatcher(refreshFn) {
    if (BC) {
      BC.addEventListener("message", function (ev) {
        if (ev.data && ev.data.type === "updated") refreshFn();
      });
    }
    if (IS_CLOUD) {
      setInterval(function () {
        if (!document.hidden) refreshFn();
      }, POLL_MS);
    }
  }

  /* ---------------- Boot ---------------- */
  document.addEventListener("DOMContentLoaded", function () {
    var ch = document.getElementById("chapter-materials");
    if (ch) initChapterMount(ch);
    var co = document.getElementById("course-materials");
    if (co) initCourseMount(co);
    var hub = document.getElementById("upload-hub");
    if (hub) initUploadHub(hub);
  });
})();
